using System;using System.Security.Cryptography;
// Same protocol plan, no I/O. Caller owns existing canonical/exclusive/native context.
sealed class SaltedSessionPlan {
 readonly object gate=new object();readonly byte[] context,salt=new byte[32],startNonce=new byte[32],proofNonce=new byte[32];byte[] key,oldNonce;uint session;int stage;public bool Retained;public string First="NONE";
 public SaltedSessionPlan(byte[] approvedContext){if(approvedContext.Length!=32)throw new InvalidOperationException("CONTEXT_SIZE");context=(byte[])approvedContext.Clone();using(RandomNumberGenerator r=RandomNumberGenerator.Create()){r.GetBytes(salt);r.GetBytes(startNonce);r.GetBytes(proofNonce);}}
 void Fail(string error){if(First=="NONE")First=error;Retained=true;stage=9;}
 public byte[] BuildStart(uint qualifiedHandle,RSACng qualifiedPublicKey,byte[] currentContext){lock(gate){if(stage!=0)throw new InvalidOperationException("ONE_SHOT");stage=1;if(!Credential.Eq(context,currentContext)){Fail("CONTEXT");throw new InvalidOperationException(First);}try{return SaltedWire.Start(qualifiedHandle,startNonce,Credential.Rsa(qualifiedPublicKey,salt,false,"SECRET"));}catch{Fail("START_PREPARATION");throw;}}}
 public byte[] AcceptStartAndBuildQuery(byte[] response,byte[] currentContext){lock(gate){if(stage!=1)throw new InvalidOperationException("ONE_SHOT");stage=2;try{if(!Credential.Eq(context,currentContext))throw new InvalidOperationException("CONTEXT");session=SaltedWire.StartResponse(response,out oldNonce);key=SaltedWire.Kdf(salt,"ATH",oldNonce,startNonce,256);return SaltedWire.Query(session,key,proofNonce,oldNonce);}catch{Fail("START_RESPONSE_UNKNOWN");throw;}}}
 public bool AcceptProof(byte[] response,byte[] currentContext){lock(gate){if(stage!=2)return false;stage=3;if(!Credential.Eq(context,currentContext)){Fail("CONTEXT");return false;}byte[] recovered;if(!SaltedWire.Verify(response,key,proofNonce,out recovered)){Fail("PROOF_RESPONSE_UNKNOWN");return false;}Array.Clear(recovered,0,recovered.Length);return true;}}
 public void Stop(){lock(gate){Fail("STOP");}}
 public void CloseFactualContext(){lock(gate){stage=4;Array.Clear(salt,0,salt.Length);Array.Clear(startNonce,0,startNonce.Length);Array.Clear(proofNonce,0,proofNonce.Length);if(key!=null)Array.Clear(key,0,key.Length);if(oldNonce!=null)Array.Clear(oldNonce,0,oldNonce.Length);}}
}
class SessionPlanTests {
 static int checks;static void C(bool x){checks++;if(!x)throw new Exception("CHECK_"+checks);}
 static byte[] B(byte v){byte[] b=new byte[32];for(int j=0;j<32;j++)b[j]=v;return b;}
 static byte[] MockReply(RSACng privateSoftware,byte[] start,out byte[] startReply,out byte[] key){byte[] salt=Credential.Rsa(privateSoftware,SaltedWire.Slice(start,54,256),true,"SECRET"),startNonce=SaltedWire.Slice(start,20,32),nonce=B(6);key=SaltedWire.Kdf(salt,"ATH",nonce,startNonce,256);Array.Clear(salt,0,salt.Length);startReply=Credential.Cat(new byte[]{0x80,1},Credential.D(48),Credential.D(0),Credential.D(0x02000001),new byte[]{0,32},nonce);return nonce;}
 static byte[] ProofReply(byte[] key,byte[] query){byte[] caller=SaltedWire.Slice(query,20,32),nonce=B(7),material=SaltedWire.Kdf(key,"CFB",nonce,caller,256);byte[] cipher=NativeCfb.Encrypt(SaltedWire.Slice(material,0,16),SaltedWire.Slice(material,16,16),B(8));byte[] parameters=Credential.Cat(new byte[]{0,32},cipher),mac=Credential.Mac(key,Credential.Cat(SaltedWire.Hash(Credential.Cat(Credential.D(0),Credential.D(0x17b),parameters)),nonce,caller,new byte[]{0x40}));Array.Clear(material,0,material.Length);return Credential.Cat(new byte[]{0x80,2},Credential.D(117),Credential.D(0),Credential.D(34),parameters,new byte[]{0,32},nonce,new byte[]{0x40,0,32},mac);}
 static int Main(){using(RSACng privateSoftware=new RSACng(2048))using(RSACng publicOnly=new RSACng()){publicOnly.ImportParameters(privateSoftware.ExportParameters(false));byte[] ctx=B(1);
 for(int mode=0;mode<6;mode++){SaltedSessionPlan p=new SaltedSessionPlan(ctx);byte[] start=p.BuildStart(0x81000001,publicOnly,ctx),sr,key;MockReply(privateSoftware,start,out sr,out key);byte[] query=p.AcceptStartAndBuildQuery(sr,ctx),reply=ProofReply(key,query);if(mode==1)reply[116]^=1;if(mode==2)p.Stop();if(mode==3)p.CloseFactualContext();C(p.AcceptProof(reply,mode==4?B(2):ctx)==(mode==0||mode==5));C(!p.AcceptProof(reply,ctx));p.CloseFactualContext();Array.Clear(key,0,key.Length);}
 SaltedSessionPlan first=new SaltedSessionPlan(ctx),second=new SaltedSessionPlan(ctx);byte[] a=first.BuildStart(0x81000001,publicOnly,ctx),b=second.BuildStart(0x81000001,publicOnly,ctx);C(!Credential.Eq(a,b));first.CloseFactualContext();second.CloseFactualContext();
 SaltedSessionPlan bad=new SaltedSessionPlan(ctx);bad.BuildStart(0x81000001,publicOnly,ctx);bool denied=false;try{bad.AcceptStartAndBuildQuery(new byte[10],ctx);}catch(InvalidOperationException){denied=true;}C(denied&&bad.Retained&&bad.First=="START_RESPONSE_UNKNOWN");bad.Stop();C(bad.First=="START_RESPONSE_UNKNOWN");bad.CloseFactualContext();
 }
 Console.WriteLine("PASS checks="+checks+" FRESH_SALT_NONCES_ONE_SESSION_PLAN_MOCK_ONLY; NO_TPM");return 0;}
}
